) AS (
  VALUES 
    (180::BIGINT, 'Es una profesora difícil de abordar, no responde correos y prefiere resolver las consultas en clase. Era su primera vez impartiendo Dinámica de la Cultura, por lo que hubo fallas de organización y comunicación. Sus lecciones resultan aburridas. Aunque obtener cien es muy sencillo, no es la mejor.'::TEXT, 10.0::NUMERIC(3,1), 6.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY['Asistencia obligatoria']::TEXT[], '2026-07-11T00:00:00+00:00'::TIMESTAMPTZ, '652b3e99c11ce7c1e817293d58b7cec1b9b39818dddb3d2a638c87afd514ec2f'::TEXT, ARRAY[506]::BIGINT[]),
    (180::BIGINT, 'Las clases son demasiado divertidas, y se disfrutan bastante, es un curso en el que se desestresa un rato y va a conocer a mucha gente porque va a bailar con tod@s, la profe es muy amable y paciente y se aprende un montón, la recomiendo totalmente, quiero danza 2!'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Inspirador', 'Tomaría su clase nuevamente']::TEXT[], '2025-11-20T00:00:00+00:00'::TIMESTAMPTZ, 'ff16cde17de3cf8ccf13a8718d6baa3e571e8d2513473f39a790a16d9199a968'::TEXT, ARRAY[500]::BIGINT[]),
    (180::BIGINT, 'Fue un curso para atender a bailar que disfruté mucho. La profe crea un ambiente seguro y se puede vacilar. Hay un montaje final al que hay que dedicarle tiempo. Quisiera danza 2'::TEXT, 6.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['La participación importa', 'Brinda apoyo', 'Clases excelentes']::TEXT[], '2025-10-18T00:00:00+00:00'::TIMESTAMPTZ, '676b269bc3e2c1cbbaaacf7f5dde7efbd28378953e22e4d849409a651e7c291d'::TEXT, ARRAY[500]::BIGINT[]),
    (180::BIGINT, 'Me encantó llevar danza! Se aprende: Merengue, salsa, bachata, swing criollo, bolero y chachachá, entre otros ritmos. Deja un par de tareas, como buscar canciones del género que se está viendo e ir a ver un espectáculo y hacer un reporte. Es dulce pero un poco estricta y se le tiene mucho respeto.'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Respetado por los estudiantes', 'Tomaría su clase nuevamente']::TEXT[], '2025-06-18T00:00:00+00:00'::TIMESTAMPTZ, 'd3941a5375442baec9db58b361c44cd63a93d06f9867da00741a15e8eef5da75'::TEXT, ARRAY[500]::BIGINT[]),
    (180::BIGINT, 'Es un clase que funciona para hacer otra cosas en el TEC y uno logra distraerse. Bailar un rato y conocer gente. Quiero danza 2'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY['Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2025-02-11T00:00:00+00:00'::TIMESTAMPTZ, 'c0a3188cd182c12fc9a8c7830b8b9d2a8a042df0b5740c1e64d4c04d935f4b17'::TEXT, ARRAY[500]::BIGINT[]),
    (180::BIGINT, 'Es buena profe, trata de explicar las cosas con claridad pero asume que uno va a ser capaz de bailar bien a la primera, más cuando los ritmos solo se ven durante 2 clases. De todas formas, el curso no tiene ninguna complicación y además es sumamente disfrutable si el baile está entre sus intereses.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación']::TEXT[], '2025-02-09T00:00:00+00:00'::TIMESTAMPTZ, 'd1f0b592560205af1ab2efad10ab7fcfd39b580cc7fcdbeb2d1d496c6f01999c'::TEXT, ARRAY[500]::BIGINT[]),
    (180::BIGINT, 'Una excelente profesora, sus explicaciones son muy precisas y se enfoca en poder mostrarle a cada estudiante los pasos. Nota: Danza imparte merengue, bachata, salsa, bolero, chachachá, y swing criollo.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2025-02-09T00:00:00+00:00'::TIMESTAMPTZ, '1694f85cbaaee71c12b72c309ff61fc6139d6c5ca9d6b99bdaad1abd820b0af3'::TEXT, ARRAY[500]::BIGINT[]),
    (180::BIGINT, 'Es una profe muy comprensiva. El curso es de baile popular y no de contemporaneo. Me encantó aprender a bailar. En verano es un éxito.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY['Asistencia obligatoria', 'Inspirador', 'Tomaría su clase nuevamente']::TEXT[], '2025-01-30T00:00:00+00:00'::TIMESTAMPTZ, 'eb117c7582f6737dfdd440c494c32a35314c72d4982291b28fb738213eafb40a'::TEXT, ARRAY[500]::BIGINT[]),
    (180::BIGINT, 'Es buena persona PERO si usted no sabe nada de baile ella es grosera y te hace sentir como idiota. Las clases pueden ser divertidas pero si no te gusta un ritmo o no sabes bailarlo se vuelve pesado. Los trabajos que deja estorban. Puede ser muy cansado si tiene mucha carga académica'::TEXT, 8.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Inspirador', 'Brinda apoyo', 'Muchos proyectos grupales']::TEXT[], '2024-10-24T00:00:00+00:00'::TIMESTAMPTZ, 'c1007dc1ee43789531857b713d3ac98ab2b1bf47c52d4ccf620274136ec678ec'::TEXT, ARRAY[500]::BIGINT[]),
    (180::BIGINT, 'Brinda un espacio divertido y diferente dentro de la U. Lo único es que deja hacer un informe, y una exposición, que dependiendo de la carga académica de otras materias, se puede volver tedioso. Fuera de eso, lo recomiendo mil, una cultural disfrutable y súper pasable!'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2024-06-27T00:00:00+00:00'::TIMESTAMPTZ, '4e917dc0719b673b3ba77c1d82ca630a8201ab68cc1ab5348a59cc4f1d78059e'::TEXT, ARRAY[500]::BIGINT[]),
    (180::BIGINT, 'Sí le gusta bailar o quiere aprender, matricule con Laura! Es una muy buena profe, y el foco de enseñanza no solo es el baile, sino sus raíces e impacto. Clases súper dinámicas. Se tiene que hacer exposiciones, una coreo, y un reporte (si de verdad le interesa, no lo deje para el final)'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Asistencia obligatoria', 'Inspirador']::TEXT[], '2024-06-26T00:00:00+00:00'::TIMESTAMPTZ, '6a97f4e9fba73aa86ba3022c738d3992a0d04fcacbb009d94226219d7c905088'::TEXT, ARRAY[500]::BIGINT[]),
    (180::BIGINT, 'Se aprende: Merengue, salsa, bachata, swing criollo, bolero clásico y chachachá. Deja un par de tareas como buscar canciones del género que se está viendo, e ir a ver un expectáculo y hacer un reporte. El reporte vale un 10% y pasa sobradisimo sin el reporte. Califica súper suave, súper comprensiva.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Clases excelentes', 'Muchos proyectos grupales', 'Tomaría su clase nuevamente']::TEXT[], '2024-06-13T00:00:00+00:00'::TIMESTAMPTZ, '86a7177b008979d7568becd66963018072ce6fa26c15b9bb6083d4af7f134bc7'::TEXT, ARRAY[500]::BIGINT[]),
    (180::BIGINT, 'Es una clase linda, la recomiendo para la cultural. El unico problema es que nos pone a hacer trabajos que dan mucha pereza y que siempre quedan todos atravesados. Pero fuera de eso la clase super bonito todo.'::TEXT, 6.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Muchas tareas', 'Asistencia obligatoria', 'Tomaría su clase nuevamente']::TEXT[], '2024-05-17T00:00:00+00:00'::TIMESTAMPTZ, 'c1374ae108dbaaff483d4a6feb2bc8630ec55521b329009b9e3f65d0cecc210e'::TEXT, ARRAY[500]::BIGINT[]),
    (180::BIGINT, 'La profe es muy buena gente, pero si uno no entiende a la primera puede ser un poco grosera, así que yo no recomendaría matricular con ella si usted no sabe nada de baile.'::TEXT, 8.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['La participación importa', 'Asistencia obligatoria', 'Tomaría su clase nuevamente']::TEXT[], '2023-12-04T00:00:00+00:00'::TIMESTAMPTZ, '2ea03988611206d9ef3c8d9b4537072fb849ad7f5ceea58dd6ee8815b474607f'::TEXT, ARRAY[500]::BIGINT[]),
    (180::BIGINT, 'Muy lindo el curso y la verdad la profe es muy buena nota, pero hay que hacer varios trabajos que dan mucha pereza de ahí en fuera, el curso es interesante para aquel que le gustaría aprender a bailar'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2023-12-03T00:00:00+00:00'::TIMESTAMPTZ, 'c498b1c9ea345d76ae5a422ba263ef77b8d05af4e3c0854f7969ac1f01368deb'::TEXT, ARRAY[500]::BIGINT[]),
    (180::BIGINT, 'Tienen que matricular este curso'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY['Inspirador', 'Clases excelentes']::TEXT[], '2023-08-10T00:00:00+00:00'::TIMESTAMPTZ, 'd282a81895b229e5c33e6db64005b37164fcd7286ea3fc4476e72c1e805b0b2e'::TEXT, ARRAY[500]::BIGINT[]),
    (180::BIGINT, 'Logra crear un espacio donde todo mundo se sienta cómodo bailando sin importar si sabe o no sabe bailar. Logra transmitir ese cariño por la danza y hace que uno se interese por aprender más. La recomiendo'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY['Inspirador', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2023-06-20T00:00:00+00:00'::TIMESTAMPTZ, 'a7ea01e611ca48b63a324afc2b0a950b0877a719de643845b57080bab9ea8a7c'::TEXT, ARRAY[500]::BIGINT[]),
    (180::BIGINT, 'La mejor clase que he tenido, vale la pena.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Inspirador', 'Brinda apoyo', 'Tomaría su clase nuevamente']::TEXT[], '2023-06-17T00:00:00+00:00'::TIMESTAMPTZ, 'c5ba5fbd277092d8dd59513cf0a9ec1e793406877558ea46c35e18a5203e753c'::TEXT, ARRAY[500]::BIGINT[]),
    (180::BIGINT, 'Es una muy buena profe'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY['Asistencia obligatoria', 'Inspirador', 'Tomaría su clase nuevamente']::TEXT[], '2023-02-07T00:00:00+00:00'::TIMESTAMPTZ, '1e5886d285ea6d8ee73f079d1104167c4847c09314f0b4d6fbdcaa7490d3a648'::TEXT, ARRAY[500]::BIGINT[]),
    (180::BIGINT, 'Es una profe muy buena. Las clases son algo diferentes al resto y funcionan para distraerse.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['La participación importa', 'Brinda apoyo', 'Clases excelentes']::TEXT[], '2022-08-04T00:00:00+00:00'::TIMESTAMPTZ, '9c10fed72ad0a3a81a7f854203a9fd89943c526dc0fa78a3e331527cefa2164d'::TEXT, ARRAY[500]::BIGINT[]),
    (180::BIGINT, 'Si sabe bailar de fijo la pasa con 100. Ella no explica mucha técnica en sí, solo deja videos para repasar antes de la clase presencial. Al final del semestre evalúa todos los ritmos (salsa, bachata...) y hay que hacer una coreo grupal. Lo más tedioso son los informes sobre obras de danza.'::TEXT, 10.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2022-06-22T00:00:00+00:00'::TIMESTAMPTZ, '0e01908f83a191d49d96b5aec62a1d09850f3182dc5084bfe26ba6aa40711cf7'::TEXT, ARRAY[500]::BIGINT[]),
    (180::BIGINT, 'mmmm no es la mejor, una clase que se pasa fácil se convierte en tediosa, no sé no la recomiendo, que pereza.'::TEXT, 4.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2020-02-07T00:00:00+00:00'::TIMESTAMPTZ, '2d59632874ff55af99e611d93010281c431a6a1acdd4d08dd63df9550d239c0e'::TEXT, ARRAY[500]::BIGINT[]),
    (180::BIGINT, 'Ninguno'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['La participación importa', 'Asistencia obligatoria', 'Muchos proyectos grupales']::TEXT[], '2018-12-06T00:00:00+00:00'::TIMESTAMPTZ, '381a6d4e25e69f622e1703064ce490a80eb54398ead3b78ce5e8a90b94e618b6'::TEXT, ARRAY[500]::BIGINT[]),
    (180::BIGINT, 'Las clases son excelentes. Se aprende mucho. la pereza son los informes que deja, pide muchos detalles. Las clases son muy relax y divertidas.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Muchas tareas', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2018-11-27T00:00:00+00:00'::TIMESTAMPTZ, 'f03ca24e1d96666748f7ff72b177a3291b567ac7b18d059838bd468c62c8508f'::TEXT, ARRAY[500]::BIGINT[]),
    (180::BIGINT, 'Ninguno'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Asistencia obligatoria']::TEXT[], '2018-07-16T00:00:00+00:00'::TIMESTAMPTZ, '2471ab39822a28d68f361cb49db55e9b9196c045e9495c48994a0b362df158e6'::TEXT, ARRAY[500]::BIGINT[]),
    (180::BIGINT, 'Es una clase relax, que se disfruta mucho pero siempre hay que estar activo.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['La participación importa', 'Asistencia obligatoria', 'Tomaría su clase nuevamente']::TEXT[], '2018-06-18T00:00:00+00:00'::TIMESTAMPTZ, 'af119396845b695c04b0f26527fb6695b8f5588a67dc4fa985a6421b9b1de879'::TEXT, ARRAY[500]::BIGINT[]),
    (180::BIGINT, 'Muy buena. Hay que ponerle.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['La participación importa']::TEXT[], '2017-09-02T00:00:00+00:00'::TIMESTAMPTZ, '71a41674d1f71d7f430dfd1acda782f2a6a73a7ac525f8feb703ccbff4e15adc'::TEXT, ARRAY[500]::BIGINT[]),
    (180::BIGINT, 'En verano es mucho mejor, se aprovecha más las horas y hay más tiempo de práctica.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['La participación importa']::TEXT[], '2017-08-08T00:00:00+00:00'::TIMESTAMPTZ, '3aa9e6d9e2c74d91839779ecb5e1f35954fb22f6b507f971aff6847731231fe3'::TEXT, ARRAY[500]::BIGINT[]),
    (180::BIGINT, 'Es muy buena, deja trabajos pero es bonito ir a ver espectáculos. Hay que ponerle y se aprende mucho.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2017-07-10T00:00:00+00:00'::TIMESTAMPTZ, '7685d700880f78e5a295a7ce8c22d39c4ce4808869b078621b1228d35a412cce'::TEXT, ARRAY[500]::BIGINT[]),
    (180::BIGINT, 'Ninguno'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Asistencia obligatoria', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2017-06-30T00:00:00+00:00'::TIMESTAMPTZ, 'f536994f9ad174ccf2d1591d2cfd19d6c6be0c852930b3d06d03dea86f7e0eb2'::TEXT, ARRAY[500]::BIGINT[]),
    (180::BIGINT, 'excelente profe.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Da crédito extra']::TEXT[], '2017-06-27T00:00:00+00:00'::TIMESTAMPTZ, 'b0ae638b86fd5a75a4fad34f98c154d34368aabebb1d63ffbda99868d38b8ca1'::TEXT, ARRAY[500]::BIGINT[]),
    (180::BIGINT, 'Asistir a clases y ponerle al trabajo final.'::TEXT, 6.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['La participación importa']::TEXT[], '2017-06-21T00:00:00+00:00'::TIMESTAMPTZ, 'dbf4df571ce5f928e1fa64cff0b34596f3d2e99e31ed74574249403194f8e1af'::TEXT, ARRAY[500]::BIGINT[]),
    (180::BIGINT, 'Una profe que cree que da un curso de carrera, los trabajos que pone son algo cansinos y la coreografía es una porquería. Además se supone que la mayoría van a aprender y es lo que menos pasa en ese curso, mama a los que saben bailar pero los que no saben, los manda a tomar por culo.'::TEXT, 6.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor']::TEXT[], '2017-02-03T00:00:00+00:00'::TIMESTAMPTZ, '3bf58450b7cb07f052acf52b4894337717da3ec1815a5e4c43abad7510525b33'::TEXT, ARRAY[500]::BIGINT[]),
    (180::BIGINT, 'vaya siempre a clases y todo bien'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2017-01-03T00:00:00+00:00'::TIMESTAMPTZ, '19d5241e6d95e0017177073ee167b1bcf5f9157a66afa0b6e81a41accd2850fb'::TEXT, ARRAY[500]::BIGINT[]),
    (180::BIGINT, 'Honestamente, ella intenta ser buena gente. Pero no lo logra. Si usted sabe bailar, lo va a mamar, pero si usted va a aprender (para lo que se supone que es el curso) y de verdad no sabe nada, ella lo va a tratar bastante regular. No la recomiendo.'::TEXT, 6.0::NUMERIC(3,1), 4.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2016-11-24T00:00:00+00:00'::TIMESTAMPTZ, '4a27028eb82b4d1db28a4567af9f84e7366971cdba7dbd98ef94ba53b587f4ef'::TEXT, ARRAY[500]::BIGINT[]),
    (180::BIGINT, 'Al principio dice: "aprovechen y disfruten de la clase, va a ser divertido", pero de alguna manera ella sabe cómo matarle lo bonito a un curso'::TEXT, 6.0::NUMERIC(3,1), 6.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF('45','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2015-12-03T00:00:00+00:00'::TIMESTAMPTZ, '937f298d79e0cc93f807848fabf31f8405413a6af817fb7d1194e16bc2899817'::TEXT, ARRAY[500]::BIGINT[]),
    (180::BIGINT, 'No es lo que uno espera de danza, ella manda un par de trabajos con su dificulta y es muy exigente. A mi parecer, no enseña los bailes y sus pasos de la manera adecuada'::TEXT, 6.0::NUMERIC(3,1), 6.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2015-11-04T00:00:00+00:00'::TIMESTAMPTZ, '3a197705714727c7f82d030530c4ab316781616dc1e24fbd99dfe0853d37a5ad'::TEXT, ARRAY[500]::BIGINT[]),
    (180::BIGINT, 'Excelente profe'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2015-06-09T00:00:00+00:00'::TIMESTAMPTZ, '9de02b983045c1c9e28ca7e9804ae53c68dcc7383827d1c205402a392c27c494'::TEXT, ARRAY[500]::BIGINT[]),
    (180::BIGINT, 'Muy buena profesora'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2014-12-09T00:00:00+00:00'::TIMESTAMPTZ, '6da80821dc218e4f0adc52ab93062eb1f9210549152dc39f1bab556d600079bc'::TEXT, ARRAY[500]::BIGINT[]),
    (180::BIGINT, 'muy buena profe, las clases son bonitas'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2014-11-18T00:00:00+00:00'::TIMESTAMPTZ, '84698f8358b694b71266c08f72ffecfadef6286f8cd9e946e7b9bb83d1c8fc7f'::TEXT, ARRAY[500]::BIGINT[]),
    (180::BIGINT, 'Ninguno'::TEXT, 8.0::NUMERIC(3,1), 3.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF('50','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2014-11-18T00:00:00+00:00'::TIMESTAMPTZ, '042e5664c3e65717f514df3c28a2148bb4150d54a000065f0c3a81c526716c92'::TEXT, ARRAY[500]::BIGINT[])
), inserted_review AS (
  INSERT INTO public.professor_review (
    professor_id, comment, ease_score, quality_score, clarity_score, fairness_score,
    attendance_required, grade_received, engagement_level, tags, status, reviewed_at, created_at, updated_at, import_key
  )
  SELECT 
    professor_id, comment, ease_score, quality_score, clarity_score, fairness_score,
    attendance_required, grade_received, engagement_level, tags, 'approved'::public.professor_review_status, now(), created_at, created_at, import_key
  FROM review_input ri
  WHERE NOT EXISTS (
    SELECT 1 FROM public.professor_review pr WHERE pr.import_key = ri.import_key
  )
  RETURNING id, import_key
), target_review AS (
  SELECT id, import_key FROM inserted_review
  UNION ALL
  SELECT pr.id, pr.import_key
  FROM public.professor_review pr
  JOIN review_input ri ON ri.import_key = pr.import_key
)
INSERT INTO public.professor_review_course (review_id, course_id)
SELECT tr.id, course_id
FROM target_review tr
JOIN review_input ri ON ri.import_key = tr.import_key
CROSS JOIN LATERAL unnest(ri.course_ids) AS course_id
ON CONFLICT DO NOTHING;

COMMIT;
